% Decision variables: digits of the PIN
var 1..9: a; % first digit cannot be 0
var 0..9: b;
var 0..9: c;
var 0..9: d;

% Constraints
constraint alldifferent([a, b, c, d]); % no two digits are the same

% cd is 3 times ab
constraint (10*c + d) == 3 * (10*a + b);

% da is 2 times bc
constraint (10*d + a) == 2 * (10*b + c);

solve satisfy;

% Output the PIN in JSON format
output [
    "{",
    join(",", [
        "\"" ++ "a" ++ "\": " ++ show(a),
        "\"" ++ "b" ++ "\": " ++ show(b),
        "\"" ++ "c" ++ "\": " ++ show(c),
        "\"" ++ "d" ++ "\": " ++ show(d)
    ]),
    "}"
];
```

