% Input data
int: n = 20; % total steps
int: m1 = 3; % minimum step size
int: m2 = 5; % maximum step size
int: max_moves = n; % maximum possible moves (each move is at least 1 step)

% Decision Variables
array[1..max_moves] of var 0..m2: steps; % steps taken in each move (0 means no move)

% Constraints
% The sum of all steps must equal n
constraint sum(steps) = n;

% Each non-zero step must be between m1 and m2
constraint forall(i in 1..max_moves) (
    steps[i] = 0 \/ (steps[i] >= m1 /\ steps[i] <= m2)
);

% All steps after the first 0 must be 0 (no moves after reaching the top)
constraint forall(i in 1..max_moves-1) (
    steps[i] = 0 -> steps[i+1] = 0
);

solve satisfy;

% Output the steps as a JSON list
output [
    "{",
    "\"" ++ "steps" ++ "\": [" ++ join(",", [show(steps[i]) | i in 1..max_moves]) ++ "]",
    "}"
];
```

