% Countries: 1=Belgium, 2=Denmark, 3=France, 4=Germany, 5=Netherlands, 6=Luxembourg
int: num_countries = 6;
set of int: COUNTRIES = 1..num_countries;

% Adjacency list from the input graph
array[int] of set of int: adjacency = [
    {3, 1}, % Edge between 3 and 1
    {3, 6}, % Edge between 3 and 6
    {3, 4}, % Edge between 3 and 4
    {6, 4}, % Edge between 6 and 4
    {6, 1}, % Edge between 6 and 1
    {1, 5}, % Edge between 1 and 5
    {1, 4}, % Edge between 1 and 4
    {4, 5}, % Edge between 4 and 5
    {4, 2}  % Edge between 4 and 2
];

% Decision variables: color for each country (1..max_colors)
var int: max_colors;
array[COUNTRIES] of var 1..num_countries: colors;

% Constraints
constraint forall(e in adjacency) (
    colors[min(e)] != colors[max(e)] % Neighboring countries must have different colors
);

% Minimize the number of colors used
constraint max_colors = max(colors);

solve minimize max_colors;

% Output the solution in JSON format
output [
    "{",
    "\"" ++ "colors" ++ "\": [" ++ join(", ", [show(colors[c]) | c in COUNTRIES]) ++ "]",
    "}"
];
