% Input data
int: num_cows = 25;
int: num_sons = 5;
array[1..num_sons] of int: cows_per_son = [7, 6, 5, 4, 3];
array[1..num_cows] of int: milk_production = [i | i in 1..num_cows];

% Decision Variables
array[1..num_cows] of var 0..num_sons-1: cow_assignments;

% Constraints
constraint global_cardinality(cow_assignments, [i | i in 0..num_sons-1], cows_per_son);

% Each son should have the same total milk production
array[0..num_sons-1] of var int: son_milk;
constraint forall(s in 0..num_sons-1) (
    son_milk[s] = sum([milk_production[c] * (cow_assignments[c] == s) | c in 1..num_cows])
);
constraint all_equal(son_milk);

% Solve
solve satisfy;

% Output
output [
    "{",
    "\"" ++ "cow_assignments" ++ "\": [" ++ join(",", [show(cow_assignments[c]) | c in 1..num_cows]) ++ "]",
    "}"
];
```

