include "alldifferent.mzn";

% Floors are numbered 1 to 5
int: num_floors = 5;
set of int: FLOORS = 1..num_floors;

% Decision variables: floor each person lives on
var FLOORS: B; % Baker
var FLOORS: C; % Cooper
var FLOORS: F; % Fletcher
var FLOORS: M; % Miller
var FLOORS: S; % Smith

% Constraints
constraint alldifferent([B, C, F, M, S]);

% Baker does not live on the fifth floor
constraint B != 5;

% Cooper does not live on the first floor
constraint C != 1;

% Fletcher does not live on either the fifth or the first floor
constraint F != 5 /\ F != 1;

% Miller lives on a higher floor than Cooper
constraint M > C;

% Smith does not live on a floor adjacent to Fletcher
constraint abs(S - F) > 1;

% Fletcher does not live on a floor adjacent to Cooper
constraint abs(F - C) > 1;

solve satisfy;

output [
    "{",
    join(",", [
        "\"" ++ "B" ++ "\": " ++ show(B),
        "\"" ++ "C" ++ "\": " ++ show(C),
        "\"" ++ "F" ++ "\": " ++ show(F),
        "\"" ++ "M" ++ "\": " ++ show(M),
        "\"" ++ "S" ++ "\": " ++ show(S)
    ]),
    "}"
];
```

