constraint forall(g in 1..num_gates) (
    apples[g-1] >= 2 % Must have at least 2 apples to give half plus one
    /\ apples[g] == apples[g-1] - (apples[g-1] div 2 + 1)
);

% Solve to find any valid solution
solve satisfy;

% Output the solution in JSON format
output [
    "{",
    "\"" ++ "apples" ++ "\": [" ++ join(", ", [show(apples[g]) | g in 0..num_gates]) ++ "]",
    "}"
];
