include "globals.mzn";

% Input data
int: num_people = 8;
array[1..num_people] of set of int: compatible = [
    {2, 3},
    {1, 6},
    {1, 4, 7},
    {2},
    {2},
    {5},
    {8},
    {3}
];

% Decision Variables: transplants[i][j] = 1 if person i donates to person j, else 0
array[1..num_people, 1..num_people] of var 0..1: transplants;

% Constraints
constraint forall(i in 1..num_people, j in 1..num_people) (
    transplants[i,j] = 1 -> j in compatible[i]
);

% Each person can donate at most once
constraint forall(i in 1..num_people) (
    sum(j in 1..num_people)(transplants[i,j]) <= 1
);

% Each person can receive at most one kidney
constraint forall(j in 1..num_people) (
    sum(i in 1..num_people)(transplants[i,j]) <= 1
);

% Anyone who donates must receive a kidney
constraint forall(i in 1..num_people) (
    sum(j in 1..num_people)(transplants[i,j]) = sum(k in 1..num_people)(transplants[k,i])
);

% Objective: Maximize the number of people receiving a kidney
var int: total_receivers = sum(i in 1..num_people, j in 1..num_people)(transplants[i,j]);
solve maximize total_receivers;

% Output the solution in JSON format
output [
    "{",
    "\"" ++ "transplants" ++ "\": [" ++ 
    join(",\n", [
        "[" ++ join(",", [show(transplants[i,j]) | j in 1..num_people]) ++ "]" 
        | i in 1..num_people
    ]) ++ "]",
    "}"
];
```

