include "globals.mzn";

int: n = 4;
set of int: N = 1..n;
set of int: N2 = 1..n*n;

% The magic square
array[N, N] of var N2: square;

% The magic constant
int: magic_constant = n * (n*n + 1) div 2;

% All numbers must be distinct and between 1 and n^2
constraint all_different([square[i, j] | i in N, j in N]);

% Rows must sum to the magic constant
constraint forall(i in N) (
    sum([square[i, j] | j in N]) = magic_constant
);

% Columns must sum to the magic constant
constraint forall(j in N) (
    sum([square[i, j] | i in N]) = magic_constant
);

% Diagonals must sum to the magic constant
constraint sum([square[i, i] | i in N]) = magic_constant;
constraint sum([square[i, n - i + 1] | i in N]) = magic_constant;

% Symmetry breaking: fix the first row and column to reduce search space
constraint square[1,1] = 1;
constraint square[1,2] = 2;
constraint square[1,3] = 3;
constraint square[1,4] = 4;
constraint square[2,1] = 5;
constraint square[3,1] = 9;
constraint square[4,1] = 13;

solve satisfy;

output [
    "{",
    "\"" ++ "square" ++ "\": [" ++ 
