% Suspects: Artie, Bill, Crackitt, Dodgy, Edgy, Fingers
enum Suspect = {ARTIE, BILL, CRACKITT, DODGY, EDGY, FINGERS};

% Decision variables: whether each suspect is guilty (true) or innocent (false)
array[Suspect] of var bool: guilty;

% Constraints based on the statements and inspector's suppositions

% At least four are innocent (so at most two are guilty)
constraint sum([guilty[s] | s in Suspect]) <= 2;

% Innocent tell the truth, guilty lie

% ARTIE: "It wasn't me."
constraint (not guilty[ARTIE]) == (not guilty[ARTIE]);

% BILL: "Crackitt was in it up to his neck."
constraint (not guilty[BILL]) == (guilty[CRACKITT]);

% CRACKITT: "No I wasn't."
constraint (not guilty[CRACKITT]) == (not guilty[CRACKITT]);

% DODGY: "If Crackitt did it, Bill did it with him."
constraint (not guilty[DODGY]) == 
    (guilty[CRACKITT] -> guilty[BILL]);

% EDGY: "Nobody did it alone."
constraint (not guilty[EDGY]) == 
    (sum([guilty[s] | s in Suspect]) != 1);

% FINGERS: "That’s right: it was Artie and Dodgy together."
constraint (not guilty[FINGERS]) == 
    (guilty[ARTIE] /\ guilty[DODGY]);

solve satisfy;

output [
    "{",
    join(",", [
        "\"" ++ "artie" ++ "\": " ++ show(guilty[ARTIE]),
        "\"" ++ "bill" ++ "\": " ++ show(guilty[BILL]),
        "\"" ++ "crackitt" ++ "\": " ++ show(guilty[CRACKITT]),
        "\"" ++ "dodgy" ++ "\": " ++ show(guilty[DODGY]),
        "\"" ++ "edgy" ++ "\": " ++ show(guilty[EDGY]),
        "\"" ++ "fingers" ++ "\": " ++ show(guilty[FINGERS])
    ]),
    "}"
];
