array[1..num_jobs, 1..2] of int: resource_needs = [|0, 0 |5, 1 |0, 4 |1, 4 |1, 3 |3, 2 |3, 1 |2, 4 |4, 0 |5, 2 |2, 5 |0, 0|];
array[1..2] of int: resource_capacities = [6, 8];
int: num_precedences = 18;
array[1..num_precedences, 1..2] of int: successors_link = [|0, 1 |0, 2 |0, 3 |1, 4 |1, 5 |2, 9 |2, 10 |3, 8 |4, 6 |4, 7 |5, 9 |5, 10 |6, 8 |6, 9 |7, 8 |8, 11 |9, 11 |10, 11|];

% Decision Variables
array[1..num_jobs] of var 0..sum(durations): start_time;
var 0..sum(durations): makespan;

% Constraints
% Precedence constraints
constraint forall(p in 1..num_precedences) (
    start_time[successors_link[p, 2] + 1] >= start_time[successors_link[p, 1] + 1] + durations[successors_link[p, 1] + 1]
);

% Resource constraints
constraint forall(r in 1..2) (
    forall(t in 0..sum(durations)) (
        sum(j in 1..num_jobs where start_time[j] <= t /\ t < start_time[j] + durations[j]) (resource_needs[j, r]) <= resource_capacities[r]
    )
);

% Makespan is the maximum end time
constraint makespan = max([start_time[i] + durations[i] | i in 1..num_jobs]);

% Objective: minimize makespan
solve minimize makespan;

% Output in JSON format
output [
    "{",
    "\"" ++ "start_time" ++ "\": [" ++ join(", ", [show(start_time[i]) | i in 1..num_jobs]) ++ "]",
    "}"
];
