     1, 1, 2, 1,
     1, 3, 2, 1,
     1, 1, 3, 2]);

% Decision Variables
array[1..3] of var 1..num_cards: winning_cards;
constraint all_different(winning_cards);
constraint winning_cards[1] < winning_cards[2] /\ winning_cards[2] < winning_cards[3];

