predicate is_set(int: c1, int: c2, int: c3) =
    let {
        % Extract features for each card
        int: n1 = cards_data[c1, 1];
        int: n2 = cards_data[c2, 1];
        int: n3 = cards_data[c3, 1];

        int: f1 = cards_data[c1, 2];
