        int: co1 = cards_data[c1, 3];
        int: co2 = cards_data[c2, 3];
        int: co3 = cards_data[c3, 3];

        int: s1 = cards_data[c1, 4];
        int: s2 = cards_data[c2, 4];
        int: s3 = cards_data[c3, 4];
