    ((f1 == f2 /\ f2 == f3) \/ (f1 != f2 /\ f2 != f3 /\ f1 != f3)) /\
    ((co1 == co2 /\ co2 == co3) \/ (co1 != co2 /\ co2 != co3 /\ co1 != co3)) /\
    ((s1 == s2 /\ s2 == s3) \/ (s1 != s2 /\ s2 != s3 /\ s1 != s3));

constraint is_set(winning_cards[1], winning_cards[2], winning_cards[3]);

solve satisfy;

output [
    "{",
    "\"" ++ "winning_cards" ++ "\": [" ++ join(",", [show(winning_cards[i]) | i in 1..3]) ++ "]",
    "}"
];
