include "globals.mzn";

% Input data: city locations
int: num_cities = 12;
array[1..num_cities] of tuple(int, int): locations = [
    (288, 149), (288, 129), (270, 133), (256, 141), (256, 163), (246, 157),
    (236, 169), (228, 169), (228, 148), (220, 164), (212, 172), (204, 159)
];

% Precompute distance matrix
array[1..num_cities, 1..num_cities] of int: dist;
constraint forall(i, j in 1..num_cities) (
    dist[i,j] = round(sqrt((locations[i].1 - locations[j].1)^2 + (locations[i].2 - locations[j].2)^2))
);

% Decision variables: tour order (permutation of cities)
array[1..num_cities] of var 1..num_cities: tour;

% The tour must be a permutation
constraint alldifferent(tour);

% The tour must start and end at the same city (cycle)
constraint tour[1] = 1; % Start at city 1 (arbitrary choice)
constraint tour[num_cities] = 1; % End at city 1

% Calculate total travel distance
var int: travel_distance = sum(i in 1..num_cities-1) (dist[tour[i], tour[i+1]]);

% Solve to minimize travel distance
solve minimize travel_distance;

% Output the optimal travel distance in JSON format
output [
    "{",
    "\"" ++ "travel_distance" ++ "\": " ++ show(travel_distance),
    "}"
];
```

