include "globals.mzn";

% Input data
array[1..3] of string: names = ["Agatha herself", "the butler", "Charles"];

% Decision Variables
set of int: PEOPLE = 1..3;
var PEOPLE: killer;

array[PEOPLE, PEOPLE] of var bool: hates;
array[PEOPLE] of var int: richer; % richer[i] represents the wealth of person i

% Constraints
constraint killer != 1; % Agatha cannot kill herself

% A killer always hates, and is no richer than his victim.
constraint hates[killer, 1] == true;
constraint richer[killer] <= richer[1];

% Charles hates no one that Agatha hates.
constraint forall(p in PEOPLE where hates[1, p])(not hates[3, p]);

% Agatha hates everybody except the butler.
constraint hates[1, 1] == false; % Agatha does not hate herself
constraint hates[1, 2] == false; % Agatha does not hate the butler
constraint hates[1, 3] == true; % Agatha hates Charles

% The butler hates everyone not richer than Aunt Agatha.
constraint forall(p in PEOPLE)(richer[p] <= richer[1] -> hates[2, p] == true);

% The butler hates everyone whom Agatha hates.
constraint forall(p in PEOPLE)(hates[1, p] -> hates[2, p] == true);

% No one hates everyone.
constraint forall(p in PEOPLE)(exists(q in PEOPLE)(not hates[p, q]));

solve satisfy;

output [
    "{",
    "\"" ++ "killer" ++ "\": " ++ show(killer),
    "}"
];
```

