include "globals.mzn";

% Input data
int: stage = 8; % Number of stages

% Decision Variables: positions at each stage (0: starting shore, 1: destination shore)
array[1..stage] of var 0..1: wolf_pos;
array[1..stage] of var 0..1: goat_pos;
array[1..stage] of var 0..1: cabbage_pos;
array[1..stage] of var 0..1: boat_pos;

% Constraints

% Initial state: all on starting shore, boat on starting shore
constraint wolf_pos[1] == 0;
constraint goat_pos[1] == 0;
constraint cabbage_pos[1] == 0;
constraint boat_pos[1] == 0;

% Final state: all on destination shore
constraint wolf_pos[stage] == 1;
constraint goat_pos[stage] == 1;
constraint cabbage_pos[stage] == 1;
constraint boat_pos[stage] == 1;

% Transition constraints between stages
constraint forall(t in 1..stage-1) (
    % Boat must move in each transition
    boat_pos[t+1] != boat_pos[t] /\

    % Farmer is always in the boat (implicit)

    % Only one item can change position (the one being carried)
    let {
        var int: changes = 
            (if wolf_pos[t] != wolf_pos[t+1] then 1 else 0 endif) +
            (if goat_pos[t] != goat_pos[t+1] then 1 else 0 endif) +
            (if cabbage_pos[t] != cabbage_pos[t+1] then 1 else 0 endif)
    } in changes <= 1 /\

    % The item being carried must be on the same side as the boat before moving
    (wolf_pos[t] == boat_pos[t] \/ goat_pos[t] == boat_pos[t] \/ cabbage_pos[t] == boat_pos[t] \/ 
     (wolf_pos[t] != boat_pos[t] /\ goat_pos[t] != boat_pos[t] /\ cabbage_pos[t] != boat_pos[t])) /\

    % Safety constraints: wolf and goat cannot be left alone, goat and cabbage cannot be left alone
    (wolf_pos[t+1] != goat_pos[t+1] \/ boat_pos[t+1] == goat_pos[t+1]) /\
    (goat_pos[t+1] != cabbage_pos[t+1] \/ boat_pos[t+1] == goat_pos[t+1])
);

solve satisfy;

% Output the solution in JSON format
output [
    "{",
    join(",", [
        "\"" ++ "wolf_pos" ++ "\": " ++ show(wolf_pos),
        "\"" ++ "goat_pos" ++ "\": " ++ show(goat_pos),
        "\"" ++ "cabbage_pos" ++ "\": " ++ show(cabbage_pos),
        "\"" ++ "boat_pos" ++ "\": " ++ show(boat_pos)
    ]),
    "}"
];
```

