include "globals.mzn";

% Input data
int: num_cars = sum(demand);
int: num_types = length(demand);
int: num_options = length(at_most);

array[1..num_options] of int: at_most;
array[1..num_options] of int: per_slots;
array[1..num_types] of int: demand;
array[1..num_types, 1..num_options] of int: requires;

% Decision Variables
array[1..num_cars] of var 1..num_types: sequence;

% Constraints
% Ensure the demand for each car type is met
constraint global_cardinality(sequence, [i | i in 1..num_types], demand);

% For each option, ensure that in any window of per_slots[o] consecutive cars,
% at most at_most[o] cars require that option
constraint forall(o in 1..num_options) (
    forall(i in 1..num_cars - per_slots[o] + 1) (
        sum(j in i..i + per_slots[o] - 1) (
            requires[sequence[j], o]
        ) <= at_most[o]
    )
);

solve satisfy;

% Output the sequence in JSON format
output [
    "{",
    "\"" ++ "sequence" ++ "\": [" ++ join(", ", [show(sequence[i]-1) | i in 1..num_cars]) ++ "]",
    "}"
];
```

