include "globals.mzn";

% Input data
int: n_teams = 9;
int: n_days = 18;
set of int: TEAMS = 1..n_teams;
set of int: DAYS = 1..n_days;
set of int: WEEKDAYS = {1,3,5,7,9,11,13,15,17};
set of int: WEEKENDS = {2,4,6,8,10,12,14,16,18};

% Mirroring scheme
array[1..9, 1..2] of int: mirroring_scheme = [|1,8 | 2,9 | 3,12 | 4,13 | 5,14 | 6,15 | 7,16 | 10,17 | 11,18|];

% Team names (for output)
array[TEAMS] of string: team_names = ["Clem", "Duke", "FSU", "GT", "UMD", "UNC", "NCSt", "UVA", "Wake"];

% Rival pairs
array[1..4, 1..2] of int: rivals = [|2,6 | 1,4 | 7,9 | 5,8|]; % Duke-UNC, Clem-GT, NCSt-Wake, UMD-UVA

% Decision Variables
array[TEAMS, DAYS] of var 0..n_teams: config; % 0 means bye
array[TEAMS, DAYS] of var -1..1: where; % -1: away, 0: bye, 1: home

% Constraints

% Mirroring constraint
constraint forall(m in 1..9) (
    forall(t in TEAMS) (
        config[t, mirroring_scheme[m,1]] = config[t, mirroring_scheme[m,2]] /\
        where[t, mirroring_scheme[m,1]] = where[t, mirroring_scheme[m,2]]
    )
);

% No two final aways
constraint forall(t in TEAMS) (
    not (where[t, n_days-1] = -1 /\ where[t, n_days] = -1)
);

% Home/Away/Bye pattern constraints
constraint forall(t in TEAMS) (
    % No more than two away in a row
    forall(d in 1..n_days-2) (
        sum([where[t, d+i] = -1 | i in 0..2]) <= 2
    ) /\
    % No more than two home in a row
    forall(d in 1..n_days-2) (
        sum([where[t, d+i] = 1 | i in 0..2]) <= 2
    ) /\
    % No more than three away or bye in a row
    forall(d in 1..n_days-3) (
        sum([where[t, d+i] != 1 | i in 0..3]) <= 3
    ) /\
    % No more than four home or bye in a row
    forall(d in 1..n_days-4) (
        sum([where[t, d+i] != -1 | i in 0..4]) <= 4
    )
);

% Weekend pattern: 4 home, 4 away, 1 bye
constraint forall(t in TEAMS) (
    sum([where[t, d] = 1 | d in WEEKENDS]) = 4 /\
    sum([where[t, d] = -1 | d in WEEKENDS]) = 4 /\
    sum([where[t, d] = 0 | d in WEEKENDS]) = 1
);

% First weekends: at least two home or bye in first five weekends
constraint forall(t in TEAMS) (
    sum([where[t, d] != -1 | d in {2,4,6,8,10}]) >= 2
);

% Rival matches
constraint forall(r in 1..4) (
    let {int: t1 = rivals[r,1], int: t2 = rivals[r,2]} in
    (config[t1, n_days] = t2 \/ config[t1, n_days] = 3 \/ where[t1, n_days] = 0) /\
    (config[t2, n_days] = t1 \/ config[t2, n_days] = 3 \/ where[t2, n_days] = 0)
);

% Constrained matches in dates 11-18
constraint 
    exists(d in 11..18) (config[9, d] = 6 /\ where[9, d] = 1) /\ % Wake-UNC
    exists(d in 11..18) (config[9, d] = 2 /\ where[9, d] = 1) /\ % Wake-Duke
    exists(d in 11..18) (config[4, d] = 6 /\ where[4, d] = 1) /\ % GT-UNC
    exists(d in 11..18) (config[4, d] = 2 /\ where[4, d] = 1);   % GT-Duke

% Opponent sequence constraints
constraint forall(t in TEAMS) (
    forall(d in 1..n_days-1) (
        not (where[t, d] = -1 /\ where[t, d+1] = -1 /\ config[t, d] = 6 /\ config[t, d+1] = 2)
    ) /\
    forall(d in 1..n_days-2) (
        not (config[t, d] = 6 /\ config[t, d+1] = 2 /\ config[t, d+2] = 9)
    )
);

% Other constraints
constraint 
    config[6, n_days] = 2 /\ where[6, n_days] = 1 /\ % UNC plays Duke last date
    config[6, 11] = 2 /\ where[6, 11] = 1 /\        % UNC plays Duke date 11
    config[6, 2] = 1 /\ where[6, 2] = 1 /\           % UNC plays Clem date 2
    where[2, 16] = 0 /\                              % Duke bye date 16
    where[9, 17] != 1 /\                             % Wake not home date 17
    where[9, 1] = 0 /\                               % Wake bye date 1
    where[1, n_days] != -1 /\ where[2, n_days] != -1 /\ where[5, n_days] != -1 /\ where[9, n_days] != -1 /\
    where[1, 1] != -1 /\ where[3, 1] != -1 /\ where[4, 1] != -1 /\ where[9, 1] != -1 /\
    where[3, n_days] != 0 /\ where[7, n_days] != 0 /\
    where[6, 1] != 0;

% Solve
solve satisfy;

% Output
output [
    "{",
    "\"config\": [", 
    join(",\n", [
        "[" ++ join(",", [show(config[t, d]) | d in DAYS]) ++ "]" | t in TEAMS
    ]),
    "],\n\"where\": [",
    join(",\n", [
        "[" ++ join(",", [show(where[t, d]) | d in DAYS]) ++ "]" | t in TEAMS
    ]),
    "]",
    "}"
];
