set of int: TEAMS = 0..n_teams-1;
set of int: WEEKS = 1..n_weeks;
set of int: PERIODS = 1..n_periods;

% Decision variables: home and away teams for each week and period
array[WEEKS, PERIODS] of var TEAMS: home;
array[WEEKS, PERIODS] of var TEAMS: away;

% Constraints

% 1. Every team plays once a week (either home or away)
constraint forall(w in WEEKS, t in TEAMS) (
    sum(p in PERIODS)(home[w,p] == t) + sum(p in PERIODS)(away[w,p] == t) = 1
);

% 2. Every team plays at most twice in the same period over the tournament
constraint forall(p in PERIODS, t in TEAMS) (
    sum(w in WEEKS)(home[w,p] == t \/ away[w,p] == t) <= 2
);

% 3. Every team plays every other team (single round robin)
constraint forall(t1, t2 in TEAMS where t1 < t2) (
    exists(w in WEEKS, p in PERIODS)((home[w,p] == t1 /\ away[w,p] == t2) \/ (home[w,p] == t2 /\ away[w,p] == t1))
);

% Symmetry breaking: fix first week's matches
constraint forall(p in PERIODS) (
    home[1,p] = 2*(p-1) /\ away[1,p] = 2*(p-1)+1
);

solve satisfy;

output [
    "{",
    join(",", [
        "\"" ++ "home" ++ "\": [" ++ 
            join(",\n", [
                "[" ++ join(",", [show(home[w,p]) | p in PERIODS]) ++ "]" 
