```minizinc
include "globals.mzn";

% Input data
int: n = 8; % Number of words to find
int: word_length = 8;
set of int: POSITIONS = 1..word_length;
set of int: WORDS = 1..n;

% Alphabet encoding: A=0, C=1, G=2, T=3
int: A = 0; int: C = 1; int: G = 2; int: T = 3;
set of int: ALPHABET = {A, C, G, T};
set of int: CG = {C, G};

% Decision Variables: words[word, position]
array[WORDS, POSITIONS] of var ALPHABET: words;

% Constraints

% Each word has exactly 4 symbols from {C,G}
constraint forall(w in WORDS) (
    sum(p in POSITIONS)(words[w,p] in CG) == 4
);

% Each pair of distinct words differ in at least 4 positions
constraint forall(w1, w2 in WORDS where w1 < w2) (
    sum(p in POSITIONS)(words[w1,p] != words[w2,p]) >= 4
);

% Function to compute reverse of a word
function array[POSITIONS] of var ALPHABET: reverse_word(array[POSITIONS] of var ALPHABET: word) =
    [word[word_length - p + 1] | p in POSITIONS];

% Function to compute Watson-Crick complement of a word
function array[POSITIONS] of var ALPHABET: complement_word(array[POSITIONS] of var ALPHABET: word) =
    [if word[p] == A then T 
     elseif word[p] == T then A 
     elseif word[p] == C then G 
     else C endif | p in POSITIONS];

% Each pair of words x and y (may be identical) must satisfy that x^R and y^C differ in at least 4 positions
constraint forall(x, y in WORDS) (
    sum(p in POSITIONS)(reverse_word([words[x,p] | p in POSITIONS])[p] != complement_word([words[y,p] | p in POSITIONS])[p]) >= 4
);

solve satisfy;

% Convert word to string representation
function string: word_to_str(array[POSITIONS] of var ALPHABET: word) =
    concat([if fix(word[p]) == A then "A" 
            elseif fix(word[p]) == C then "C" 
            elseif fix(word[p]) == G then "G" 
            else "T" endif | p in POSITIONS]);

output [
    "{",
    "\"" ++ "words" ++ "\": [" ++ 
