include "globals.mzn";

int: N = 10; % Number of vertices
set of int: VERTICES = 1..N;
array[VERTICES] of var 1..N: degrees; % Degrees of each vertex, must be >0 and mod 3
var int: sum_degrees; % Sum of degrees, must be mod 12

% Constraints on degrees
constraint forall(i in VERTICES)(degrees[i] mod 3 == 0);
constraint sum_degrees = sum(degrees);
constraint sum_degrees mod 12 == 0;
constraint decreasing(degrees); % Ensure degree sequence is non-increasing

% Adjacency matrix
array[VERTICES, VERTICES] of var bool: matrix;
constraint forall(i in VERTICES)(matrix[i,i] == false); % No self-loops
constraint forall(i,j in VERTICES where i < j)(matrix[i,j] == matrix[j,i]); % Undirected graph
constraint forall(i in VERTICES)(sum([matrix[i,j] | j in VERTICES]) == degrees[i]); % Degree constraints

% Diamond-free constraint: no 4 vertices with >=5 edges
constraint forall(a,b,c,d in VERTICES where a < b /\ b < c /\ c < d)(
    (matrix[a,b] + matrix[a,c] + matrix[a,d] + matrix[b,c] + matrix[b,d] + matrix[c,d]) <= 4
);

% Symmetry breaking: enforce lexicographic order on adjacency matrix rows
constraint lex_lesseq([matrix[i,j] | i,j in VERTICES where i < j], [matrix[i,j] | i,j in VERTICES where i > j]);

solve satisfy;

% Output the adjacency matrix in JSON format
output [
    "{",
    "\"" ++ "matrix" ++ "\": [",
    join(",\n", [
        "[" ++ join(",", [show(matrix[i,j]) | j in VERTICES]) ++ "]" | i in VERTICES
    ]),
    "]",
    "}"
];
