% Define the seating positions (circular table, so positions 0 and 5 are adjacent)
set of int: POSITIONS = 0..num_guests-1;

% Decision variable: x[p] is the guest at position p
array[POSITIONS] of var GUESTS: x;

% Constraints
constraint all_different(x);

% Define who can sit next to whom
% Each guest can only sit next to certain other guests
constraint forall(p in POSITIONS) (
    let {
        int: left_pos = if p == 0 then num_guests-1 else p-1 endif,
        int: right_pos = if p == num_guests-1 then 0 else p+1 endif
    } in
    (x[p] == 0) -> (x[left_pos] == 3 \/ x[left_pos] == 5) /\ (x[right_pos] == 3 \/ x[right_pos] == 5) % Andrew
    /\
    (x[p] == 1) -> (x[left_pos] == 2 \/ x[left_pos] == 4) /\ (x[right_pos] == 2 \/ x[right_pos] == 4) % Betty
    /\
    (x[p] == 2) -> (x[left_pos] == 1 \/ x[left_pos] == 5) /\ (x[right_pos] == 1 \/ x[right_pos] == 5) % Cara
