include "globals.mzn";

% Input data
int: n = 5;
int: grid_size = n * n;

% Decision Variables: grid[x,y] represents the number at position (x,y)
array[1..n, 1..n] of var 1..grid_size: x;

% Constraints
constraint all_different([x[i,j] | i in 1..n, j in 1..n]);

% For each number from 2 to n^2, enforce movement rules based on previous position
constraint forall(k in 2..grid_size) (
    exists(i1 in 1..n, j1 in 1..n, i2 in 1..n, j2 in 1..n) (
        x[i1,j1] == k-1 /\ x[i2,j2] == k /\
        (
            % Movement Type I: vertical/horizontal with 2-square gap
            ((abs(i1 - i2) == 3 /\ j1 == j2) \/ (abs(j1 - j2) == 3 /\ i1 == i2)) \/
            % Movement Type II: diagonal with 1-square gap
            (abs(i1 - i2) == 2 /\ abs(j1 - j2) == 2)
        )
    )
);

% Break symmetry by fixing the first number to position (1,1)
constraint x[1,1] == 1;

solve satisfy;

% Output the grid in JSON format
output [
    "{",
    "\"" ++ "x" ++ "\": [",
    join(",\n", [
        "[" ++ join(",", [show(x[i,j]) | j in 1..n]) ++ "]" | i in 1..n
    ]),
    "]",
    "}"
];
```

