include "globals.mzn";

% Input data
int: num_crew = 20;
int: num_flights = 10;
array[1..num_crew, 1..5] of int: attributes;
array[1..num_flights, 1..6] of int: required_crew;

% Decision Variables
array[1..num_crew, 1..num_flights] of var 0..1: crew;

% Constraints
constraint forall(f in 1..num_flights) (
    % Total crew required
    sum(c in 1..num_crew)(crew[c, f]) = required_crew[f, 1]
);

constraint forall(f in 1..num_flights) (
    % Stewards required
    sum(c in 1..num_crew where attributes[c, 1] = 1)(crew[c, f]) >= required_crew[f, 2]
);

constraint forall(f in 1..num_flights) (
    % Hostesses required
    sum(c in 1..num_crew where attributes[c, 2] = 1)(crew[c, f]) >= required_crew[f, 3]
);

constraint forall(f in 1..num_flights) (
    % French speaking required
    sum(c in 1..num_crew where attributes[c, 3] = 1)(crew[c, f]) >= required_crew[f, 4]
);

constraint forall(f in 1..num_flights) (
    % Spanish speaking required
    sum(c in 1..num_crew where attributes[c, 4] = 1)(crew[c, f]) >= required_crew[f, 5]
);

constraint forall(f in 1..num_flights) (
    % German speaking required
    sum(c in 1..num_crew where attributes[c, 5] = 1)(crew[c, f]) >= required_crew[f, 6]
);

% Every cabin crew member has two flights off after an attended flight
constraint forall(c in 1..num_crew) (
    forall(f in 1..num_flights-2) (
        crew[c, f] + crew[c, f+1] + crew[c, f+2] <= 1
    )
);

solve satisfy;

output [
    "{",
    "\"crew\": [",
    join(",\n", [
        "[" ++ join(",", [show(crew[c, f]) | f in 1..num_flights]) ++ "]" 
        | c in 1..num_crew
    ]),
    "]",
    "}"
];
```

